import{_ as a,c as p,o as t,ah as n}from"./chunks/framework.BxT5r71R.js";const h=JSON.parse('{"title":"2024年表","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART3/0_2024年表.md","filePath":"zh-cn/Management2/PART3/0_2024年表.md"}'),r={name:"zh-cn/Management2/PART3/0_2024年表.md"};function o(i,e,_,S,s,E){return t(),p("div",null,[...e[0]||(e[0]=[n('<h2 id="第三部分" tabindex="-1">第三部分 <a class="header-anchor" href="#第三部分" aria-label="Permalink to &quot;第三部分&quot;">​</a></h2><p>2024年的BMSG</p><p>1月17日 Novel Core首次在日本武道馆举办演出。</p><p>2月13日 BMSG发布《BMSG关于避免音乐行业走向不可持续的倡议》。</p><p>3月2日、3日 BE:FIRST首次在东京巨蛋举办演出。4月20日、21日还在京瓷巨蛋大阪举办演出。</p><p>4月15日 第二次举办商业会议Greeting &amp; Gathering&#39;24。</p><p>4月24日 BE:FIRST发行单曲《Masterplan》。此次发行试行多项举措，包括从CD制造阶段大幅减少塑料用量，减少随CD附送的特典（编者注：指购买唱片时附送的赠品或其他权益），并直接销售与这些特典价值相当的周边商品。</p><p>5月1日 SKY-HI参与企划的新音乐节目《Apartment B》开播。</p><p>5月29日 BMSG POSSE由SKY-HI、Novel Core、Aile The Shota、edhiii boi、REIKO共5人组成，当天以数字形式发行歌曲《Girlfriend》。</p><p>6月1日 MAZZEL启动首次全国巡演MAZZEL 1st One Man Tour 2024 “Join us in the PARADE”，在日本八座城市举办九场演出。</p><p>7月1日 BE:FIRST与韩国男子唱跳组合ATEEZ的合作歌曲《Hush-Hush》上线。</p><p>7月2日 Aile The Shota首次个人专场巡演从横滨KT Zepp Yokohama启程，在日本五座城市举办五场演出。</p><p>7月20日、21日 BE:FIRST担任ATEEZ美国洛杉矶演出的开场嘉宾，首次登上海外舞台。</p><p>8月28日 BE:FIRST发行第二张专辑《2:BE》。</p><p>9月18日 BMSG成立4周年。</p><p>9月21日、22日、23日 第三届BMSG FES——BMSG FES&#39;24在K-Arena横滨举办。</p><p>9月23日 BMSG宣布启动男子组合选秀企划THE LAST PIECE，旨在组建旗下第三组男子组合。</p><p>10月1日、2日 MAZZEL在横滨Pia Arena MM首次举办Arena场馆（大型室内场馆）演出。10月15日、16日还在大阪城音乐厅举办演出。</p><p>10月4日 Chanmina担任制作人的女子组合选秀节目《No No Girls》上线开播。</p>',19)])])}const l=a(r,[["render",o]]);export{h as __pageData,l as default};
